function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 6);
  const value = (parity) => {
    const v = 1 + Math.floor(rand() * 100);
    return parity === undefined || v % 2 === parity ? v : (v === 100 ? 99 : v + 1);
  };
  const mode = rand();
  if (mode < 0.4) return [Array.from({ length: n }, () => value())];
  const start = Math.floor(rand() * 2);
  const nums = Array.from({ length: n }, (_, i) => value((start + i) % 2));
  if (mode < 0.7 && n > 1) {
    // Break the alternation at one place so the answer is false.
    const at = 1 + Math.floor(rand() * (n - 1));
    nums[at] = value(nums[at - 1] % 2);
  }
  return [nums];
}
